bool extract_archive(struct archive *src, const char *dest_path) {
    struct archive *out;
    struct archive_entry *entry;
    int flags = ARCHIVE_EXTRACT_TIME | ARCHIVE_EXTRACT_PERM | ARCHIVE_EXTRACT_NOCHOWN | ARCHIVE_EXTRACT_NOCHMOD;
    int r;
    char full_path[4096];

    // Initialize the archive writer
    out = archive_write_disk_new();
    if (!out) {
        return false;
    }
    archive_write_disk_set_options(out, flags);

    // Read and extract each entry
    while ((r = archive_read_next_header(src, &entry)) == ARCHIVE_OK) {
        // Sanitize the filename to prevent path traversal
        const char *entry_path = archive_entry_pathname(entry);
        if (entry_path == NULL || *entry_path == '\0') {
            // Skip empty filenames
            continue;
        }

        // Check for path traversal attempts
        if (strchr(entry_path, '/')) {
            // Skip entries with slashes (to prevent directory traversal)
            continue;
        }

        // Build full path
        snprintf(full_path, sizeof(full_path), "%s/%s", dest_path, entry_path);
        archive_entry_set_pathname(entry, full_path);

        // Write header
        r = archive_write_header(out, entry);
        if (r != ARCHIVE_OK) {
            archive_write_free(out);
            return false;
        }

        // Copy data
        const void *buff;
        size_t size;
        la_int64_t offset;
        while ((r = archive_read_data_block(src, &buff, &size, &offset)) == ARCHIVE_OK) {
            if (archive_write_data_block(out, buff, size, offset) != ARCHIVE_OK) {
                archive_write_free(out);
                return false;
            }
        }
        if (r != ARCHIVE_EOF) {
            archive_write_free(out);
            return false;
        }
    }

    archive_write_free(out);
    return r == ARCHIVE_EOF ? true : false;
}

bool extract_tar_to_path(const char *tar_path, const char *dest_path) {
    struct archive *a;
    struct archive_entry *entry;
    int r;

    a = archive_read_new();
    if (a == NULL) {
        return false;
    }

    // Add tar filter
    r = archive_read_support_filter_tar(a);
    if (r != ARCHIVE_OK) {
        archive_read_free(a);
        return false;
    }

    // Open the tar file
    r = archive_read_open_filename(a, tar_path, 1024 * 1024);
    if (r != ARCHIVE_OK) {
        archive_read_free(a);
        return false;
    }

    // Extract each entry
    while ((r = archive_read_next_header(a, &entry)) == ARCHIVE_OK) {
